,"data_source_urls":["https://github.com/mstrhakr/network-list-sync","https://github.com/mstrhakr/network-list-sync/blob/main/LICENSE","https://github.com/mstrhakr/network-list-sync#quick-start","https://github.com/mstrhakr/network-list-sync/blob/main/compose.yaml","https://github.com/orgs/mstrhakr/packages/container/package/network-list-sync","https://raw.githubusercontent.com/mstrhakr/plugin-repository/master/network-list-sync.xml"]},"expected_categories":["documents-pdfs","email-newsletters","networking-dns"],"categories":["networking-dns"],"expected_sources":["https://github.com/mstrhakr/network-list-sync/issues/","https://github.com/mstrhakr/network-list-sync#readme","https://github.com/orgs/mstrhakr/packages/container/package/network-list-sync","https://raw.githubusercontent.com/mstrhakr/network-list-sync/main/docs/logo.png","https://raw.githubusercontent.com/mstrhakr/plugin-repository/master/network-list-sync.xml"],"evidence_urls":["https://github.com/mstrhakr/network-list-sync","https://github.com/mstrhakr/network-list-sync/blob/main/LICENSE","https://github.com/mstrhakr/network-list-sync#quick-start","https://github.com/mstrhakr/network-list-sync/blob/main/compose.yaml","https://github.com/orgs/mstrhakr/packages/container/package/network-list-sync","https://raw.githubusercontent.com/mstrhakr/plugin-repository/master/network-list-sync.xml"],"expected_install_options":[{"method":"docker","label":"Docker image","url":"https://ghcr.io/mstrhakr/network-list-sync","image":"ghcr.io/mstrhakr/network-list-sync:latest","support_level":"community","source_url":"https://github.com/orgs/mstrhakr/packages/container/package/network-list-sync","note":"Community-maintained image. Verify the publisher before pulling.","sort_order":10},{"method":"unraid","label":"Unraid catalog","url":"https://raw.githubusercontent.com/mstrhakr/plugin-repository/master/network-list-sync.xml","image":null,"support_level":"community","source_url":"https://raw.githubusercontent.com/mstrhakr/plugin-repository/master/network-list-sync.xml","note":"Listed in the Unraid Community Applications catalog; verify the template publisher before installing.","sort_order":35}],"reviewed_install_methods":["docker","compose"],"install_options":[{"method":"docker","label":"Docker image","url":"https://github.com/orgs/mstrhakr/packages/container/package/network-list-sync","image":"ghcr.io/mstrhakr/network-list-sync:main","support_level":"official","source_url":"https://github.com/mstrhakr/network-list-sync#quick-start","note":null,"sort_order":10},{"method":"compose","label":"Docker Compose","url":"https://github.com/mstrhakr/network-list-sync/blob/main/compose.yaml","image":null,"support_level":"official","source_url":"https://github.com/mstrhakr/network-list-sync/blob/main/compose.yaml","note":null,"sort_order":20}],"technical_updates":{"docker":{"status":"published","checked_at":"2026-09-28","confidence":"high","note":"The project recommends its GHCR image.","source_urls":["https://github.com/mstrhakr/network-list-sync#quick-start","https://github.com/orgs/mstrhakr/packages/container/package/network-list-sync"]},"compose":{"status":"published","checked_at":"2026-09-28","confidence":"high","note":"The project provides a Docker Compose deployment.","source_urls":["https://github.com/mstrhakr/network-list-sync/blob/main/compose.yaml"]},"database":{"status":"published","checked_at":"2026-09-28","confidence":"high","note":"The application stores its data in SQLite.","source_urls":["https://github.com/mstrhakr/network-list-sync#quick-start"]}}}]$batch$::jsonb;
BEGIN
  FOR app_rec IN
    SELECT * FROM jsonb_to_recordset(batch) AS x(
      slug text,
      expected jsonb,
      changes jsonb,
      expected_categories text[],
      categories text[],
      expected_sources text[],
      evidence_urls text[],
      expected_install_options jsonb,
      reviewed_install_methods text[],
      install_options jsonb,
      technical_updates jsonb
    )
  LOOP
    SELECT coalesce(array_agg(c.slug ORDER BY c.slug), '{}'::text[])
    INTO current_categories
    FROM public.self_host_app_category_links l
    JOIN public.self_host_app_categories c ON c.id=l.category_id
    JOIN public.self_host_apps a ON a.id=l.app_id
    WHERE a.slug=app_rec.slug;
    IF current_categories IS DISTINCT FROM app_rec.expected_categories THEN
      RAISE EXCEPTION '% categories changed since review', app_rec.slug;
    END IF;

    SELECT a.id INTO v_app_id
    FROM public.self_host_apps a
    WHERE a.slug=app_rec.slug
      AND a.published IS TRUE
      AND a.self_hosting_status='self_hostable'
      AND to_jsonb(a) @> app_rec.expected
      AND a.data_source_urls IS NOT DISTINCT FROM app_rec.expected_sources;
    IF v_app_id IS NULL THEN
      RAISE EXCEPTION '% app fields or source links changed since review', app_rec.slug;
    END IF;

    SELECT io.options INTO current_options
    FROM public.self_host_app_install_options io
    WHERE io.app_id=v_app_id
    FOR UPDATE;
    IF current_options IS DISTINCT FROM app_rec.expected_install_options THEN
      RAISE EXCEPTION '% install options changed since review', app_rec.slug;
    END IF;
    IF EXISTS (
      SELECT 1
      FROM jsonb_array_elements(app_rec.install_options) o
      WHERE NOT ((o->>'method') = ANY(app_rec.reviewed_install_methods))
    ) THEN
      RAISE EXCEPTION '% contains an unreviewed install method', app_rec.slug;
    END IF;

    IF (SELECT count(*) FROM public.self_host_app_categories c WHERE c.slug=ANY(app_rec.categories)) <> cardinality(app_rec.categories) THEN
      RAISE EXCEPTION '% category slug is missing', app_rec.slug;
    END IF;

    updated_row := jsonb_populate_record(null::public.self_host_apps, app_rec.changes);
    UPDATE public.self_host_apps AS a SET
    compose_support = CASE WHEN app_rec.changes ? 'compose_support' THEN updated_row.compose_support ELSE a.compose_support END,
    compose_url = CASE WHEN app_rec.changes ? 'compose_url' THEN updated_row.compose_url ELSE a.compose_url END,
    database_types = CASE WHEN app_rec.changes ? 'database_types' THEN updated_row.database_types ELSE a.database_types END,
    deployment_methods = CASE WHEN app_rec.changes ? 'deployment_methods' THEN updated_row.deployment_methods ELSE a.deployment_methods END,
    docker_image = CASE WHEN app_rec.changes ? 'docker_image' THEN updated_row.docker_image ELSE a.docker_image END,
    docker_support = CASE WHEN app_rec.changes ? 'docker_support' THEN updated_row.docker_support ELSE a.docker_support END,
    docker_url = CASE WHEN app_rec.changes ? 'docker_url' THEN updated_row.docker_url ELSE a.docker_url END,
    docs_url = CASE WHEN app_rec.changes ? 'docs_url' THEN updated_row.docs_url ELSE a.docs_url END,
    github_full_name = CASE WHEN app_rec.changes ? 'github_full_name' THEN updated_row.github_full_name ELSE a.github_full_name END,
    github_owner = CASE WHEN app_rec.changes ? 'github_owner' THEN updated_row.github_owner ELSE a.github_owner END,
    github_repo = CASE WHEN app_rec.changes ? 'github_repo' THEN updated_row.github_repo ELSE a.github_repo END,
    install_docs_url = CASE WHEN app_rec.changes ? 'install_docs_url' THEN updated_row.install_docs_url ELSE a.install_docs_url END,
    license = CASE WHEN app_rec.changes ? 'license' THEN updated_row.license ELSE a.license END,
    license_spdx_id = CASE WHEN app_rec.changes ? 'license_spdx_id' THEN updated_row.license_spdx_id ELSE a.license_spdx_id END,
    license_type = CASE WHEN app_rec.changes ? 'license_type' THEN updated_row.license_type ELSE a.license_type END,
    pricing_model = CASE WHEN app_rec.changes ? 'pricing_model' THEN updated_row.pricing_model ELSE a.pricing_model END,
    publisher_name = CASE WHEN app_rec.changes ? 'publisher_name' THEN updated_row.publisher_name ELSE a.publisher_name END,
    publisher_type = CASE WHEN app_rec.changes ? 'publisher_type' THEN updated_row.publisher_type ELSE a.publisher_type END,
    publisher_url = CASE WHEN app_rec.changes ? 'publisher_url' THEN updated_row.publisher_url ELSE a.publisher_url END,
    requires_database = CASE WHEN app_rec.changes ? 'requires_database' THEN updated_row.requires_database ELSE a.requires_database END,
    source_code_host = CASE WHEN app_rec.changes ? 'source_code_host' THEN updated_row.source_code_host ELSE a.source_code_host END,
    source_code_url = CASE WHEN app_rec.changes ? 'source_code_url' THEN updated_row.source_code_url ELSE a.source_code_url END,
    source_full_name = CASE WHEN app_rec.changes ? 'source_full_name' THEN updated_row.source_full_name ELSE a.source_full_name END,
    source_model = CASE WHEN app_rec.changes ? 'source_model' THEN updated_row.source_model ELSE a.source_model END,
    summary = CASE WHEN app_rec.changes ? 'summary' THEN updated_row.summary ELSE a.summary END,
    website_url = CASE WHEN app_rec.changes ? 'website_url' THEN updated_row.website_url ELSE a.website_url END,
    data_source_urls=app_rec.evidence_urls,
    technical_fact_status=coalesce(a.technical_fact_status, '{}'::jsonb) || app_rec.technical_updates,
    updated_at=now()
    WHERE a.id=v_app_id;
    GET DIAGNOSTICS affected = ROW_COUNT;
    IF affected <> 1 THEN RAISE EXCEPTION '% app update failed', app_rec.slug; END IF;

    IF app_rec.categories IS DISTINCT FROM app_rec.expected_categories THEN
      DELETE FROM public.self_host_app_category_links AS l WHERE l.app_id=v_app_id;
      INSERT INTO public.self_host_app_category_links (app_id, category_id)
      SELECT v_app_id, c.id
      FROM public.self_host_app_categories c
      WHERE c.slug=ANY(app_rec.categories);
    END IF;

    UPDATE public.self_host_app_install_options AS io SET
      options=app_rec.install_options,
      docker_urls=ARRAY(SELECT o->>'url' FROM jsonb_array_elements(app_rec.install_options) o WHERE o->>'method'='docker' ORDER BY (o->>'sort_order')::integer),
      docker_images=ARRAY(SELECT DISTINCT o->>'image' FROM jsonb_array_elements(app_rec.install_options) o WHERE o->>'method'='docker' AND nullif(o->>'image','') IS NOT NULL ORDER BY 1),
      compose_urls=ARRAY(SELECT o->>'url' FROM jsonb_array_elements(app_rec.install_options) o WHERE o->>'method'='compose' ORDER BY (o->>'sort_order')::integer),
      source_urls=ARRAY(SELECT DISTINCT o->>'source_url' FROM jsonb_array_elements(app_rec.install_options) o WHERE nullif(o->>'source_url','') IS NOT NULL ORDER BY 1),
      checked_at=now(),
      updated_at=now()
    WHERE io.app_id=v_app_id;
    GET DIAGNOSTICS affected = ROW_COUNT;
    IF affected <> 1 THEN RAISE EXCEPTION '% install update failed', app_rec.slug; END IF;
  END LOOP;
END
$migration$;
